import React from 'react'
import NavBar from '../../components/NavBar/NavBar'
import Footer from '../../components/Footer/Footer'
import '../pages.css'

const Lindja_me_prerja_cezariane_TEXT = () => {
  
  return (
    <div>
       <NavBar />
      <div className='articles_h' style={{width: '100%', backgroundColor: '#EF5A76', display:'flex', alignItems: 'center', justifyContent: 'center',color: '#fffffd',fontFamily: 'Abhaya Libre',letterSpacing: "10%",}}>LINDJA ME PRERJE CEZARIANE</div>
      <div className='main_context' style={{display: 'flex', justifyContent: 'center', marginBottom:50, marginTop: 10,}} >
        
        <p style={{ fontFamily:'Abhaya Libre', letterSpacing: '10%'}}>
       
        Lindja me prerje cezariane është një ndërhyrje kirurgjikale që përdoret për të sjellë bebin në jetë kur lindja natyrale nuk është e mundur ose paraqet rrezik për nënën dhe bebin. Gjatë këtij operacioni bëhet prerje në bark dhe në mitër për të nxjerrë bebin në mënyrë të sigurt. Në ditët e sotme, prerja cezariane është shumë e zakonshme dhe luan rol të rëndësishëm në parandalimin e komplikimeve gjatë lindjes.
        <br/> <br/>
        Lindja me prerje cezariane <span style={{color:'#EF5A76'}}> rekomandohet</span> në disa situata mjekësore. Ajo mund të kryhet kur bebi është në pozitë jo të rregullt, si për shembull këmbë-poshtë, kur ka distres fetal (shqetësim i bebit në mitër), placenta previa (kur placenta mbulon hapjen e mitrës), hipertension apo preeklampsi (rritje e tensionit gjatë shtatzënisë). Gjithashtu, prerja cezariane mund të rekomandohet te gratë që kanë pasur lindje të mëparshme me prerje cezariane ose kur lindja natyrale nuk po përparon normalisht. Ajo mund të jetë e planifikuar, ku data dihet paraprakisht, ose urgjente, kur vendimi merret gjatë lindjes për arsye mjekësore.
        <br/> <br/>
        Gjatë operacionit zakonisht përdoret <span style={{color:'#EF5A76'}}>anestezia spinale (ose epidurale)</span>, ku nëna qëndron zgjuar por nuk ndjen dhimbje. Në raste të caktuara urgjente mund të përdoret anestezia e përgjithshme. Operacioni zakonisht zgjat 30 deri në 60 minuta dhe prerja bëhet horizontalisht në pjesën e poshtme të barkut, e njohur si “bikini cut”. Bebi zakonisht nxirret brenda minutave të para, ndërsa gjatë gjithë procedurës nëna monitorohet vazhdimisht nga stafi mjekësor.
        <br/> <br/>
       <span style={{color:'#EF5A76'}}>Pas operacionit</span>, nëna qëndron në repartin e rikuperimit dhe mund të përjetojë dhimbje të moderuara, të përziera ose dridhje. Ushqyerja me gji rekomandohet të fillojë sa më herët që të jetë e mundur. Ditët e para pas lindjes kërkojnë kujdes të veçantë, ku qëndrimi në spital zakonisht zgjat 2–4 ditë. Ecja e lehtë rekomandohet herët për të ndihmuar qarkullimin dhe rikuperimin, ndërsa dhimbja kontrollohet me terapi të përshtatshme. Plaga kontrollohet çdo ditë dhe duhet të mbahet e pastër dhe e thatë për të shmangur infeksionin.
        <br/> <br/>
        <span style={{color:'#EF5A76'}}>Rikuperimi vazhdon edhe në shtëpi</span> dhe kërkon pushim, ushqim të shëndetshëm dhe konsumim të lëngjeve. Nënat duhet të shmangin ngritjen e peshave për rreth gjashtë javë dhe ngasjen e makinës për 2–3 javë. Është normale që dhimbja të zvogëlohet gradualisht dhe të ketë mpirje rreth plagës, pasi barku dhe muskujt kanë nevojë për kohë për t’u rikuperuar. Gjithashtu, mbështetja emocionale nga familja është shumë e rëndësishme gjatë kësaj periudhe.
        <br/> <br/>
        Edhe ushqyerja me gji pas cezarianes mund të realizohet normalisht. Pozicionet si shtrirja anash ose “futboll hold” ndihmojnë nënën të ndihet më rehat gjatë ushqyerjes. Nëse paraqiten temperaturë mbi 38°C, gjakderdhje e madhe, erë e keqe nga plaga, dhimbje të forta ose vështirësi në frymëmarrje, duhet <span style={{color:'#EF5A76'}}>kontaktuar menjëherë mjeku</span>.
        <br/> <br/>
        Në aspektin emocional, shumë nëna mund të përjetojnë ndjenja të përziera pas cezarianes, por është e rëndësishme të kuptohet se kjo nuk është “dështim” i lindjes. Çdo lindje është e vlefshme dhe prerja cezariane është një mënyrë që shpesh shpëton jetën e nënës dhe bebit. Me kujdes, durim dhe mbështetje, rikuperimi bëhet më i lehtë dhe shumica e grave mund të kenë edhe shtatzëni apo lindje normale në të ardhmen, sipas vlerësimit të mjekut.
        <br/> <br/>

      </p>
      </div>
      <Footer />
    </div>
  )
}

export default Lindja_me_prerja_cezariane_TEXT
